informal_sketch.pseudocode:
class BasicBlock:
    def __init__(self, id, wcet_no_preemption):
        self.id = id
        self.b = wcet_no_preemption # b_i_k

def calculate_C_NP(task_tau):
    C_NP_i = 0
    for k in range(1, task_tau.N + 1):
        C_NP_i += task_tau.b_values[k]
    return C_NP_i

class Task:
    def __init__(self, id, basic_blocks, preemption_overheads):
        self.id = id
        self.basic_blocks = basic_blocks # List of BasicBlock objects
        self.xi_values = preemption_overheads # xi_values[k] is xi_i_k (overhead after BB k)

class Task:
    # ... (previous attributes)
    self.selected_epps = [0] * (self.N - 1) # selected_i_k for k=0 to N-2 (0-indexed PPPs)

def calculate_C_i(task_tau):
    C_i = task_tau.C_NP
    for k in range(1, task_tau.N):
        C_i += task_tau.selected_epps[k-1] * task_tau.xi_values[k] # Assuming xi_values[k] is for PPP k
    return C_i

import math

def calculate_RBF(task_tau, interval_a):
    return math.ceil(interval_a / task_tau.T) * task_tau.C

import math

def calculate_DBF(task_tau, interval_a):
    if interval_a < task_tau.D:
        return 0
    return (math.floor((interval_a - task_tau.D) / task_tau.T) + 1) * task_tau.C

class SystemParameters:
    def __init__(self, max_npr_length):
        self.Q = max_npr_length # Q_i for a specific task i

def is_npr_valid(start_bb_idx, end_bb_idx, b_values, xi_values, Q):
    npr_wcet = calculate_npr_wcet(start_bb_idx, end_bb_idx, b_values, xi_values)
    return npr_wcet <= Q

formal_description.statement:
A task set tau is schedulable with limited preemption (EDF or FP) if, for all k | 1 <= k <= n + 1, q_max_k <= Q_k.

Under Fixed Priority (FP):
Q_k = min_{1<=i<k} {beta_FP_i}
beta_FP_i = max_{a in {D_i} union A | a <= D_i} {a - sum_{j<=i} RBF_j_a}
with A = {m * T_j | m in N, 1 <= j < n}

Under Earliest Deadline First (EDF):
Q_k = min_{1<=i<k} {beta_EDF_i}
beta_EDF_i = min_{a in A | D_i <= a < D_i+1} {a - sum_{tau_j in tau} DBF_j_a}
with A = {m * T_j + D_j | m in N, 1 <= j <= n}

Conventionally, q_max_n_plus_1 = 0, and D_n_plus_1 is min(lcm(T_1, ..., T_n), (1 / (1 - U)) * sum_{i=1}^{n} (U_i * max(0, T_i - D_i))).
